package com.example

/**
 * Complete, distinct 20 cards for Mathematics Sets 4 to 9 (120 unique cards).
 * 100% curriculum aligned with official O/L Mathematics syllabus.
 */
object FlashcardBankMathsSets {

  fun getMathSet(setNum: Int, cardNum: Int): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      4 -> mathSet4[(c - 1) % mathSet4.size]
      5 -> mathSet5[(c - 1) % mathSet5.size]
      6 -> mathSet6[(c - 1) % mathSet6.size]
      7 -> mathSet7[(c - 1) % mathSet7.size]
      8 -> mathSet8[(c - 1) % mathSet8.size]
      9 -> mathSet9[(c - 1) % mathSet9.size]
      else -> null
    }
  }

